import zipfile
import re
from xml.etree import ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships',
    'rel': 'http://schemas.openxmlformats.org/package/2006/relationships',
}

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    letters, row = m.group(1), int(m.group(2))
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - ord('A') + 1)
    return idx, row

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("FILES IN ARCHIVE:")
    for n in names:
        print(" ", n)

    # workbook sheet list
    wb = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for sh in wb.find('m:sheets', NS):
        sheets.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
    print("\nSHEETS:", sheets)

    rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rid2target = {}
    for rel in rels:
        rid2target[rel.get('Id')] = rel.get('Target')

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        sst = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in sst.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    for name, rid in sheets:
        target = rid2target.get(rid, '')
        path = 'xl/' + target if not target.startswith('/') else target[1:]
        print(f"\n=== SHEET: {name} (path={path}) ===")
        root = ET.fromstring(z.read(path))
        sheet_data = root.find('m:sheetData', NS)
        rows = {}
        max_col = 0
        for row in sheet_data.findall('m:row', NS):
            rnum = int(row.get('r'))
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                cidx, _ = col_to_idx(ref)
                max_col = max(max_col, cidx)
                t = c.get('t')
                v = c.find('m:v', NS)
                isel = c.find('m:is', NS)
                val = None
                if v is not None and v.text is not None:
                    val = v.text
                    if t == 's':
                        val = shared[int(val)]
                    elif t == 'b':
                        val = val == '1'
                    elif t == 'str':
                        pass
                    elif t is None:
                        try:
                            val = float(val)
                            if val == int(val):
                                val = int(val)
                        except ValueError:
                            pass
                elif isel is not None:
                    val = ''.join(t.text or '' for t in isel.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
                rows[(rnum, cidx)] = val
        if rows:
            rmax = max(r for r, c in rows)
            for r in range(1, rmax + 1):
                line = []
                for c in range(1, max_col + 1):
                    line.append(rows.get((r, c), ''))
                print(r, line)

import zipfile
import re
import xml.etree.ElementTree as ET

NS = "{http://schemas.openxmlformats.org/spreadsheetml/2006/main}"
RID = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"

path = "budget.xlsx"
z = zipfile.ZipFile(path)
print("FILES:", z.namelist())

shared = []
if "xl/sharedStrings.xml" in z.namelist():
    root = ET.fromstring(z.read("xl/sharedStrings.xml"))
    for si in root.findall(NS + "si"):
        shared.append("".join(t.text or "" for t in si.iter(NS + "t")))

wb = ET.fromstring(z.read("xl/workbook.xml"))
rels = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
relmap = {rel.get("Id"): rel.get("Target") for rel in rels}

def colnum(ref):
    m = re.match(r"([A-Z]+)(\d+)", ref)
    col = 0
    for ch in m.group(1):
        col = col * 26 + ord(ch) - 64
    return col, int(m.group(2))

for sheet in wb.iter(NS + "sheet"):
    name = sheet.get("name")
    rid = sheet.get(RID)
    target = relmap.get(rid, "")
    if not target.startswith("xl/"):
        target = "xl/" + target.lstrip("/")
    print(f"\n=== Sheet: {name} ({target}) ===")
    sroot = ET.fromstring(z.read(target))
    rows = {}
    for c in sroot.iter(NS + "c"):
        r = c.get("r")
        t = c.get("t")
        v = c.find(NS + "v")
        val = v.text if v is not None else None
        if t == "s" and val is not None:
            val = shared[int(val)]
        elif t == "inlineStr" and c.find(NS + "is") is not None:
            val = "".join(x.text or "" for x in c.find(NS + "is").iter(NS + "t"))
        f = c.find(NS + "f")
        if val is None and f is not None:
            val = "=" + (f.text or "")
        rows[r] = val
    for r, v in sorted(rows.items(), key=lambda kv: (colnum(kv[0])[1], colnum(kv[0])[0])):
        print(f"{r}: {v!r}")

